public function test_get_path_is_cached(): void {
    $domain = new Domain();
    $domain->set_blog_id($this->blog_id);

    // Use a filter or mock to track calls to the underlying method
    $call_count = 0;
    add_filter('get_blog_details', function($details) use (&$call_count) {
        $call_count++;
        return $details;
    }, 10, 1);

    $path1 = $domain->get_path();
    $path2 = $domain->get_path();

    $this->assertSame($path1, $path2);
